B.vC=s(["\u0642\u0628\u0644 \u0627\u0644\u0645\u064a\u0644\u0627\u062f","\u0645\u064a\u0644\u0627\u062f\u064a"],t.s)
B.c7m=new A.dQ("Bequemer Sitz","Setz dich im Schneidersitz auf ein Kissen, aufrecht, die H\xe4nde liegen auf den Knien. Atme ruhig ein und aus.",45)
B.c7d=new A.dQ("Seitliches Dehnen","Heb den rechten Arm \xfcber den Kopf und neige dich sanft nach links. Zwei tiefe Atemz\xfcge, dann Seite wechseln.",60)
B.c6T=new A.dQ("Schulterkreisen","Kreise beide Schultern langsam nach hinten, dann nach vorn.",40)
B.c7c=new A.dQ("Katze und Kuh","Geh in den Vierf\xfc\xdflerstand. Beim Ausatmen den R\xfccken runden, beim Einatmen sanft lang machen.",75)
B.c6V=new A.dQ("Kindshaltung mit weiten Knien","Setz dich auf die Fersen, \xf6ffne die Knie weit und lass den Oberk\xf6rper nach vorn sinken. Atme in den R\xfccken.",60)
B.c79=new A.dQ("Nachsp\xfcren","Setz dich wieder bequem hin, schlie\xdfe die Augen und sp\xfcr deinem Atem nach.",45)
B.bk3=s([B.c7m,B.c7d,B.c6T,B.c7c,B.c6V,B.c79],t.ka)
B.c6O=new A.ty("Sanftes Ankommen",B.hx,"Ein ruhiger Einstieg f\xfcr jeden Tag: Atem, R\xfccken und Schultern l\xf6sen.",B.bk3,"leicht")
B.c77=new A.dQ("Beckenkreisen im Sitz","Setz dich auf einen Stuhl oder Ball und kreise mit dem Becken langsam in beide Richtungen.",60)
B.c7i=new A.dQ("Vierf\xfc\xdfler, Arm und Bein","Streck einen Arm nach vorn und das gegen\xfcberliegende Bein nach hinten, kurz halten, dann wechseln. Der R\xfccken bleibt ruhig.",90)
B.c73=new A.dQ("Katze und Kuh","Runden und wieder lang machen, im Rhythmus des Atems.",60)
B.c7b=new A.dQ("Brust\xf6ffner im T\xfcrrahmen","Lege die Unterarme rechts und links an den T\xfcrrahmen und geh einen kleinen Schritt nach vorn.",45)
B.c6S=new A.dQ("Seitliches Dehnen im Stand","Steh h\xfcftbreit, heb einen Arm und neige dich zur Seite. Wechsle nach zwei Atemz\xfcgen.",60)
B.c6Y=new A.dQ("Kindshaltung","Knie weit, Oberk\xf6rper sinkt nach vorn, Stirn auf einem Kissen. Atme tief in den R\xfccken.",60)
B.bfP=s([B.c77,B.c7i,B.c73,B.c7b,B.c6S,B.c6Y],t.ka)
B.c6M=new A.ty("R\xfccken l\xf6sen",B.dC,"F\xfcr Verspannungen im unteren R\xfccken und in den Schultern, besonders wenn der Bauch w\xe4chst.",B.bfP,"leicht")
B.c6U=new A.dQ("Schmetterling","Fu\xdfsohlen aneinander, Knie fallen locker zur Seite. Ein Kissen unter dem Ges\xe4\xdf hilft.",75)
B.c74=new A.dQ("Hockstellung mit Halt","Stell dich mit gespreizten F\xfc\xdfen hin, halte dich an einem Stuhl oder Tisch fest und geh in die tiefe Hocke, soweit es angenehm ist.",60)
B.c72=new A.dQ("H\xfcftkreisen","Steh h\xfcftbreit, H\xe4nde auf der Stuhllehne, und kreise mit dem Becken in gro\xdfen Kreisen.",60)
B.c6X=new A.dQ("Ausfallschritt mit Halt","Ein Bein einen Schritt zur\xfcck, beide Knie beugen, die H\xfcfte sinkt leicht nach unten. Wechsle die Seite.",90)
B.c7a=new A.dQ("Sitz mit gespreizten Beinen","Setz dich aufrecht mit weit ge\xf6ffneten Beinen auf ein Kissen und neige dich leicht nach vorn, ohne den R\xfccken zu runden.",60)
B.c7h=new A.dQ("Beckenboden sp\xfcren","Setz dich bequem und spann den Beckenboden sanft an, dann lass ganz los.",45)
B.b8S=s([B.c6U,B.c74,B.c72,B.c6X,B.c7a,B.c7h],t.ka)
B.c6L=new A.ty("H\xfcften \xf6ffnen",B.p8,"Sanfte Dehnungen f\xfcr H\xfcfte und Beckenboden, auch zur Vorbereitung auf die Geburt.",B.b8S,"mittel")
B.c7_=new A.dQ("Ankommen","Setz dich aufrecht hin, eine Hand liegt auf dem Bauch, eine auf der Brust.",30)
B.c7l=new A.dQ("Bauchatmung","Atme so ein, dass sich vor allem die Hand am Bauch hebt, und lang wieder aus.",90)
B.c7k=new A.dQ("Rippenatmung","Lege beide H\xe4nde an die Seiten der Rippen und atme in die H\xe4nde hinein.",75)
B.c75=new A.dQ("Lange Ausatmung","Atme vier Sekunden ein und sechs Sekunden aus.",90)
B.c7g=new A.dQ("Stille","Atme normal weiter und beobachte, wie es dir geht.",45)
B.bp7=s([B.c7_,B.c7l,B.c7k,B.c75,B.c7g],t.ka)
B.c6Q=new A.ty("Atem und Ruhe",B.dC,"Kurze Atemyoga-Einheit, die dich beruhigt. Gut vor Terminen oder bei innerer Unruhe.",B.bp7,"leicht")
B.c6Z=new A.dQ("Schultern und Nacken","Setz dich aufrecht hin und lass den Kopf sanft zu jeder Seite sinken.",60)
B.c6R=new A.dQ("Katze und Kuh, langsam","Im Vierf\xfc\xdflerstand sehr langsam bewegen, jeder Atemzug eine Bewegung.",75)
B.c7e=new A.dQ("Kindshaltung","Knie weit, Oberk\xf6rper sinkt nach vorn, Arme liegen lang. Lass alles los.",90)
B.c76=new A.dQ("Seitenlage mit Kissen","Leg dich auf die linke oder rechte Seite, ein Kissen zwischen den Knien, ein Kissen unter dem Bauch.",120)
B.c71=new A.dQ("Tiefe Entspannung","Sp\xfcr, wie der Atem den K\xf6rper bewegt. Lass Kiefer, Schultern und H\xe4nde weich werden.",120)
B.biW=s([B.c6Z,B.c6R,B.c7e,B.c76,B.c71],t.ka)
B.c6P=new A.ty("Abendyoga zum Einschlafen",B.dC,"Langsame Bewegungen und Dehnungen, die den Tag ausklingen lassen. Alles in der Seitenlage oder im Sitzen.",B.biW,"leicht")
B.c7f=new A.dQ("Bauchatmung im Sitz","Setz dich bequem hin und atme tief in den Bauch. Beim Ausatmen sinkt die Bauchdecke.",75)
B.c6W=new A.dQ("Beckenboden sanft anspannen","Beim Ausatmen den Beckenboden leicht anheben und beim Einatmen ganz loslassen.",90)
B.c78=new A.dQ("Schulterkreisen","L\xf6se Nacken und Schultern, die beim Tragen und Stillen viel leisten.",60)
B.c7j=new A.dQ("Katze und Kuh","Runden und wieder lang machen. Keine tiefe R\xfcckbeuge.",75)
B.c70=new A.dQ("Kindshaltung","Knie weit, Oberk\xf6rper sinkt nach vorn. Entspanne dich.",60)
B.bnn=s([B.c7f,B.c6W,B.c78,B.c7j,B.c70],t.ka)
B.c6N=new A.ty("Sanft zur\xfcck in den K\xf6rper",B.kI,"F\xfcr die Zeit nach der Geburt, wenn Hebamme oder \xc4rztin es erlauben: Atem, Beckenboden und Haltung wieder wahrnehmen.",B.bnn,"leicht")
